// GnosticismIceberg.swift
// The first iceberg. Gnosticism — not what you think it is.
// Ron's original research and voice. Every word intentional.
// ☀️ SunFlow: Reignited

import SwiftUI

struct GnosticismIceberg {
    
    static let iceberg = Iceberg(
        id: "gnosticism",
        title: "Gnosticism",
        subtitle: "The buried map of reality they didn't want you to find",
        emoji: "🔺",
        headerGradient: [
            Color(red: 0.6, green: 0.85, blue: 1.0),
            Color(red: 0.0, green: 0.03, blue: 0.12)
        ],
        layers: [
            layer0_Surface,
            layer1_BelowTheLine,
            layer2_TwoGods,
            layer3_MaterialPrison,
            layer4_HumanCondition,
            layer5_Archons,
            layer6_SoulTrap,
            layer7_GnosticJesus,
            layer8_EdenReread,
            layer9_Implications,
        ],
        sourceNotes: "Primary sources: Nag Hammadi Library (discovered 1945), Gospel of Thomas, Gospel of Philip, Gospel of Truth, Apocryphon of John, Sophia of Jesus Christ, Pistis Sophia, Gospel of Judas. Academic references: Elaine Pagels, Marvin Meyer, Bentley Layton.",
        contentWarning: "This content presents ancient Gnostic cosmology as a framework for inquiry. It challenges mainstream religious narratives. Engage with curiosity, not certainty. Question everything — including this."
    )
    
    // MARK: - Layer 0: Surface
    
    static let layer0_Surface = IcebergLayer(
        id: "gnostic_0",
        depth: 0,
        title: "The Discovery",
        tagline: "A peasant looking for fertilizer found texts hidden for 1,600 years.",
        sections: [
            IcebergSection(heading: "What Most People Think", body: "Most people think Gnosticism is just some obscure Christian heresy, a footnote in religious history. Maybe a cult that got stamped out in the 3rd century. Some weird mystics who got too obsessed with secret knowledge and angels.\n\nThat's what I thought too — until I actually looked into what they believed. Not the sanitized version from introductory philosophy courses. The actual texts, the cosmology, the claims they made about reality itself.\n\nGnosticism wasn't just a different interpretation of Christianity. It was a completely different explanation for why the world exists at all."),
            IcebergSection(heading: "Nag Hammadi, 1945", body: "A peasant in Egypt named Muhammad Ali al-Samman was digging for fertilizer near a cliff in Nag Hammadi. His shovel hit something hard — a sealed jar about three feet tall buried in the ground.\n\nIn Egyptian folklore, jars like this could contain jinn, malevolent spirits. He hesitated. But poverty overrides superstition. He smashed the jar open.\n\nInside were 13 leather-bound codices. Books. Old books written in Coptic, an Egyptian language derived from ancient Greek. He had no idea what they said. He took them home and his mother, needing kindling for the fire, burned several pages before he stopped her.\n\nSome of the most important religious texts in human history almost became cooking fuel."),
            IcebergSection(heading: "Hidden On Purpose", body: "These weren't lost by accident. Someone hid them deliberately — probably right before they would have been destroyed, likely around 367 AD when Bishop Athanasius of Alexandria ordered the destruction of all heretical texts.\n\nSome monk, some scribe, some believer took those books, sealed them in a jar, and buried them in the desert, hoping someone in the future would understand.\n\n1,600 years later, someone did.\n\nThese were Gnostic gospels — the Gospel of Thomas, the Gospel of Philip, the Gospel of Truth, the Apocryphon of John, the Sophia of Jesus Christ. Texts that early Christians decided were too dangerous to exist. Not dangerous because they were false. Dangerous because of what they implied about the nature of God, the world, and the human soul."),
        ],
        readingMinutes: 4,
        depthLabel: "Surface"
    )
    
    // MARK: - Layer 1: Below the Waterline
    
    static let layer1_BelowTheLine = IcebergLayer(
        id: "gnostic_1",
        depth: 1,
        title: "The Iceberg",
        tagline: "Surface level is weird mysticism. The bottom is a prison map.",
        sections: [
            IcebergSection(heading: "Why It Matters", body: "These people weren't delusional. They weren't making things up for attention. They were trying to solve a problem that still haunts us today.\n\nWhy does reality feel like a trap? Why does existence feel wrong? Why do you work and struggle and achieve and still feel empty? Why does the world operate like a machine designed to grind you down no matter how hard you try?\n\nMost religions say it's a test. Punishment for sin. A lesson. You're here to grow. Suffering is temporary. Reward is coming. Just obey. Just have faith. Just endure.\n\nGnosticism says something different. Something darker. Something that once you hear it, you can't unhear it.\n\nThe suffering isn't a bug. It's a feature. And the being who designed this place isn't the true God at all."),
            IcebergSection(heading: "The Iceberg Metaphor", body: "Think of Gnosticism like an iceberg.\n\nOn the surface, it looks like just another ancient religion — strange terminology, esoteric rituals, philosophical debates about the divine. Academic stuff you'd study in a comparative religion class and forget about a week later.\n\nBut the deeper you go, the more it stops resembling theology and starts resembling something else entirely. A schematic. A map of a system you're trapped inside. A manual for escaping a prison you didn't know existed.\n\nThe surface level is weird mysticism.\nThe middle layer is cosmic horror.\nAnd the bottom — the bottom is where you start questioning whether the physical universe was ever supposed to exist in the first place."),
        ],
        readingMinutes: 3,
        depthLabel: "Below the Waterline"
    )
    
    // MARK: - Layer 2: The Two Gods
    
    static let layer2_TwoGods = IcebergLayer(
        id: "gnostic_2",
        depth: 2,
        title: "The Two Gods",
        tagline: "One true, one false. The false one is running the show.",
        sections: [
            IcebergSection(heading: "The Monad — The Real One", body: "In Gnostic cosmology, the true God — called the Monad — isn't a being, not a personality, not something you can pray to or understand in any human way. The Monad is pure consciousness without form. Infinite potential, absolute unity, beyond thought, beyond emotion, beyond existence itself.\n\nIt doesn't think. It doesn't desire. It doesn't create in the sense of planning and executing. It simply IS. And from its being, reality emanates — naturally, the way light pours from the sun without the sun deciding to shine.\n\nThese emanations are called Aeons — divine attributes expressing themselves in increasingly complex forms: Wisdom, Truth, Life, Light. Together they form the Pleroma, the fullness, a perfect self-contained cosmos of pure spirit. No conflict, no lack, no separation, no time, no decay."),
            IcebergSection(heading: "Sophia's Mistake", body: "Sophia is one of the Aeons. Her name means Wisdom. But she did something none of the other Aeons had done — she acted independently. She tried to create without the consent of the Monad, without a partner, without the balance required for stable emanation.\n\nWhat she created was wrong. Not evil. Not intentionally malicious. Just wrong — incomplete, a distortion of the divine pattern. Like trying to photocopy a photocopy of a photocopy. Each iteration loses resolution.\n\nWhat Sophia gave birth to was called Yaldabaoth — the Demiurge, the blind god, the ignorant creator."),
            IcebergSection(heading: "The False Creator", body: "Yaldabaoth is described as a lion-faced serpent — monstrous, malformed. He's not evil in the way we think of evil. He's ignorant. Cut off from the Pleroma, from the source. He opens his eyes and sees nothing — no Monad, no Aeons, just void.\n\nIn that darkness, he assumes he's alone. He assumes he's the first, the only. And so he declares:\n\n\"I am God. There is no other God besides me.\"\n\nDoes that sound familiar? Isaiah 45:5. Exodus 20:3. The God of the Bible repeatedly declares he is the only God.\n\nThe orthodox interpretation: he's asserting his supremacy.\n\nThe Gnostic interpretation: he's exposing his ignorance. A being who needs to convince himself of his own primacy because deep down he suspects something exists beyond his awareness.\n\nHe's a middle manager who thinks he owns the company because he's never met the board of directors."),
        ],
        readingMinutes: 5,
        depthLabel: "Shallow Depth"
    )
    
    // MARK: - Layer 3: The Material Prison
    
    static let layer3_MaterialPrison = IcebergLayer(
        id: "gnostic_3",
        depth: 3,
        title: "The Material Prison",
        tagline: "The universe is a rough draft made by someone without the manual.",
        sections: [
            IcebergSection(heading: "Building Without Blueprints", body: "In his ignorance, the Demiurge starts building. Stars, galaxies, planets, physical laws, time, gravity, entropy, death. He shapes the void into something structured — something that operates according to rules he can understand.\n\nBut it's not good. Not in the ultimate sense. It's limited, flawed. A prison made of geometry and physics and laws that ensure everything born will eventually die. Everything that rises will eventually fall.\n\nThink of it like building a house without knowing architecture. You might get the walls up. You might get a roof on. But the foundation will be unstable. The wiring will be dangerous. The plumbing will leak. The house will function technically, but living in it will be constant maintenance, constant problems, constant frustration.\n\nThat's the material universe. Functional but flawed. Beautiful in moments but ultimately unsustainable."),
            IcebergSection(heading: "Matter as Frozen Spirit", body: "Matter isn't inherently evil in Gnostic thought. It's just dense, slow, heavy — a crystallization of consciousness so thick it's forgotten what it is. Light compressed into form. Spirit frozen into flesh.\n\nThink of it like water. In its natural state, water is fluid, flowing, formless. Freeze it and it becomes solid, rigid, immobile. It's still water, but it's trapped in structure.\n\nThat's what matter is — frozen spirit. Consciousness locked in form. And the Demiurge is the one who froze it.\n\nBut here's the key: he didn't do it with his own light. He doesn't have light of his own. He's a shadow being, born from imbalance. The energy came from Sophia — when she gave birth to him, she inadvertently gave him a portion of her own divine essence. He used stolen light as raw material for creation."),
            IcebergSection(heading: "The Gnostic Answer to Evil", body: "This is the Gnostic answer to the problem of evil.\n\nThe world is flawed because the architect is flawed. Suffering exists because the builder of reality is ignorant. Pain is baked into the system because the being who designed it doesn't understand harmony.\n\nYou don't have to do mental gymnastics to explain why an all-powerful, all-loving god allows children to die of cancer. Why earthquakes kill thousands. Why existence is saturated with predation and decay.\n\nBecause the god running this place isn't all-loving. He's not even all-knowing. He's powerful, yes. Creative, yes. But wise? Compassionate? Connected to the ultimate source? No. He's a cosmic-level mistake running a broken system, convinced he's doing a good job."),
        ],
        readingMinutes: 5,
        depthLabel: "Mid-Depth"
    )
    
    // MARK: - Layer 4: The Human Condition
    
    static let layer4_HumanCondition = IcebergLayer(
        id: "gnostic_4",
        depth: 4,
        title: "The Divine Spark",
        tagline: "You are not from here. And part of you remembers.",
        sections: [
            IcebergSection(heading: "Accident Within an Accident", body: "Humans in the Gnostic narrative don't come from the Demiurge's plan. They come from an accident within an accident.\n\nA fragment of Sophia's light got mixed into the clay when the Demiurge was forming Adam. Suddenly, these material bodies had something they weren't supposed to have — divine consciousness.\n\nYou are not made in the image of the Demiurge. You are made from the stolen fragments of Sophia's light. The spark inside you — the thing you call awareness, the consciousness reading these words — doesn't belong to this world. It's a piece of the Pleroma trapped in flesh."),
            IcebergSection(heading: "Divine Homesickness", body: "That's why nothing here ever feels quite right. You can achieve everything society tells you to achieve — career, success, relationships, status, pleasure — and still underneath it all, there's a gnawing feeling that something's missing.\n\nThe Gnostics called this divine homesickness. Not homesickness in the sentimental sense, but a deep existential dissonance.\n\nThat feeling when you look at the stars and feel a strange pull — like you should be out there instead of here.\n\nThat feeling when you're in a crowd and suddenly feel utterly alien.\n\nThat feeling when you achieve something you've wanted for years, and it brings no satisfaction — just the realization that the wanting itself was a distraction from a deeper need you can't name.\n\nAccording to the Gnostics, that's memory. Not conscious memory — soul memory. The part of you that existed before you had a body remembers what it was like to not be trapped. And it's mourning."),
            IcebergSection(heading: "The Question", body: "The spark knows it doesn't belong here. It knows this world is a distortion. That matter is a downgrade. That time is a prison. That death is a revolving door you keep walking through, forgetting everything each time, starting over, suffering again.\n\nThe Gnostics asked a simple question:\n\nIf we're not from here, if we don't belong here — then why are we here? Not in the philosophical sense. Literally: what mechanism is keeping us here? Who benefits from our imprisonment? What force ensures we don't remember and escape?\n\nThe answer, according to the texts: the Archons."),
        ],
        readingMinutes: 5,
        depthLabel: "Deep Water"
    )
    
    // MARK: - Layer 5: The Archons
    
    static let layer5_Archons = IcebergLayer(
        id: "gnostic_5",
        depth: 5,
        title: "The Archons",
        tagline: "Cosmic bureaucrats. Middle management of a prison you didn't consent to.",
        sections: [
            IcebergSection(heading: "The Rulers", body: "The word Archon comes from the Greek archōn, meaning ruler. But in Gnostic cosmology, Archons aren't kings. They're more like cosmic bureaucrats. Middle management in a prison system you didn't consent to.\n\nCreated by the Demiurge to govern the material universe, they're extensions of his will — not omnipotent, not even particularly intelligent — but they have one job they perform with mechanical efficiency:\n\nKeep souls locked in the cycle. Keep them ignorant. Keep them distracted. Keep them from realizing they don't belong here."),
            IcebergSection(heading: "The Seven Spheres", body: "The Archons are associated with the seven planetary spheres — ancient cosmology imagined the universe as layered concentric shells. Each sphere governed by an Archon. Each one a checkpoint in a cosmic prison system.\n\nThe Moon governs emotional attachment.\nMercury governs mental conditioning.\nVenus governs desire.\nThe Sun governs ego.\nMars governs aggression.\nJupiter governs belief systems.\nSaturn governs time, limitation, death.\n\nThese aren't just physical locations — they're dimensions of control. Each sphere imposes restrictions on consciousness passing through it. The kind of power a prison wall has over a prisoner. It doesn't hate you. It just stops you from leaving."),
            IcebergSection(heading: "Control Through Deception", body: "The Archons don't rule through force. They don't need to. They rule through deception. They manipulate perception. They create systems of belief that keep you thinking the material world is all there is.\n\nSome Gnostic texts describe them as parasitic — feeding on human emotional energy. Fear, anger, despair, lust, worship, attachment — all of it generates a frequency that sustains them.\n\nThe Archons don't need to control you directly. That would be inefficient. They just need to control the narrative. Make sure you never ask the right questions. Stay focused on survival, on status, on material accumulation.\n\nAnd if you start asking questions? Everyone will think you're crazy. Because there's bills to pay and responsibilities to meet. The system polices itself."),
            IcebergSection(heading: "Metaphor or Literal?", body: "Maybe the Archons are metaphors for psychological structures — the ego, conditioning, fear-based thinking that keeps you from awakening. The internalized voice of authority that tells you to stay small.\n\nYou can apply this framework right now. Notice how you're controlled by fear, by desire, by the need for approval. Those are the Archons in action — psychologically speaking.\n\nBut the Gnostics also described them as literal beings — actual nonhuman intelligences operating in dimensions adjacent to physical reality. Not just inner demons. External forces influencing nations, starting wars, shaping history to ensure maximum suffering, maximum forgetting.\n\nThe question becomes: how much of what you think is your own thought is actually yours?"),
        ],
        readingMinutes: 6,
        depthLabel: "Deeper"
    )
    
    // MARK: - Layer 6: The Soul Trap
    
    static let layer6_SoulTrap = IcebergLayer(
        id: "gnostic_6",
        depth: 6,
        title: "The Soul Trap",
        tagline: "What if the light at the end of the tunnel is a reset button?",
        sections: [
            IcebergSection(heading: "What Happens When You Die", body: "Not the comforting version. The Gnostic version.\n\nYou die. Your consciousness separates from your body. For a moment — relief. The pain stops. The weight is gone. You feel light, free, expansive.\n\nThen you see it. The light. Bright, warm, inviting. It feels like love, like home. Everyone you've lost seems to be there, calling you forward. Beings of light, radiant and beautiful.\n\nYou move toward it naturally. Why wouldn't you?\n\nBut according to Gnostic texts, that light is not what you think it is. It's not the Pleroma. It's not salvation. It's the first checkpoint. The entry point to the Archonic spheres. The reincarnation system. The soul trap."),
            IcebergSection(heading: "The Interrogation", body: "In the Pistis Sophia, the soul's journey after death is described as an interrogation — a series of tests administered by beings who pretend to be benevolent but are actually gatekeepers.\n\nAs your consciousness ascends through the planetary spheres, each Archon stops you. Questions you. Do you know the passwords? The secret names? The words of power that grant passage?\n\nIf you don't — if you're just a soul stumbling through with no knowledge, no preparation — you're turned back. Sent down. Pushed into another body, another life, another cycle of forgetting."),
            IcebergSection(heading: "Forgetting Is the Feature", body: "Forgetting isn't an accident. It's not a natural consequence of birth. It's a feature — a built-in mechanism, a deliberate erasure that happens every time you reincarnate.\n\nThe Archons don't want you to remember. If you remember where you came from, you can't be controlled. So they wipe you every time. Strip your memories. Insert you back into matter — helpless, dependent, forced to spend years absorbing cultural programming.\n\nThis is where modern soul trap theory comes from. It's not a new age invention. It's ancient Gnosticism resurfacing.\n\nWhat if reincarnation is not spiritual evolution, but spiritual recycling?\nWhat if you're not here to learn lessons, but because you didn't escape last time?"),
            IcebergSection(heading: "Gnosis — The Way Out", body: "Salvation didn't come from faith. Not from worship. Not from being good. It came from knowledge — gnosis. The direct experiential realization that you are not your body, your thoughts, your emotions, your name.\n\nYou are the divine spark. And you have the right to leave.\n\nSome texts describe specific practices — declarations to speak to each Archon:\n\n\"I am a child of the true God. I do not belong to you. I do not owe you worship. I do not accept your authority. I am leaving and you cannot stop me.\"\n\nThis is why the knowledge was hidden. If everyone understood that reincarnation is optional, that the Archons have no real power except what you give them — the system would collapse."),
        ],
        readingMinutes: 7,
        depthLabel: "The Abyss"
    )
    
    // MARK: - Layer 7: The Gnostic Jesus
    
    static let layer7_GnosticJesus = IcebergLayer(
        id: "gnostic_7",
        depth: 7,
        title: "The Gnostic Jesus",
        tagline: "He didn't come to die for you. He came to wake you up.",
        sections: [
            IcebergSection(heading: "Revealer, Not Redeemer", body: "In Orthodox Christianity, Jesus died on the cross as a blood sacrifice to atone for humanity's sins. You're saved by faith in that sacrifice.\n\nIn Gnostic Christianity, Jesus didn't come to die for you. He came to wake you up.\n\nHe wasn't a redeemer — he was a revealer. His purpose wasn't to pay a debt to the Demiurge. It was to expose the Demiurge as a fraud, reveal the existence of the true God, and teach humans they are divine beings trapped in matter."),
            IcebergSection(heading: "The Gospel of Thomas", body: "In the Gospel of Thomas, Jesus doesn't perform miracles to prove he's divine. He teaches secrets. He speaks in riddles designed to shatter conventional thinking:\n\n\"If you bring forth what is within you, what you bring forth will save you. If you do not bring forth what is within you, what you do not bring forth will destroy you.\"\n\nThat's not about faith. That's about self-knowledge. Awakening the divine spark within.\n\n\"The kingdom of God is inside you and all around you, not in mansions of wood and stone. Split a piece of wood and I am there. Lift a stone and you will find me.\"\n\nThat's not heaven as a place you go after death. That's consciousness as the substrate of reality."),
            IcebergSection(heading: "The Gospel of Judas", body: "In the Gospel of Judas, Judas isn't a traitor. He's the only disciple who understands what Jesus is actually doing.\n\nThe other disciples worship Jesus as a god. They want miracles and prophecies. But Judas understands: Jesus is demonstrating that the body is not the self, that death is not the end, that consciousness transcends matter.\n\nThe crucifixion isn't a sacrifice to God — it's a demonstration. A public execution of flesh to show that the Christ within cannot be killed.\n\nThe message: You are not a sinner begging for mercy. You are a divine being who has forgotten your origin. The kingdom of God isn't a place you go when you die. It's a state of awareness you can access right now — if you stop believing the lies."),
            IcebergSection(heading: "Why the Church Rejected It", body: "If salvation comes from inner knowledge, you don't need the institution. If every person can access the divine directly, the hierarchy collapses. If Christ is a state of consciousness — not a person you worship — then organized religion becomes obsolete.\n\nA religion based on obedience is stable. Controllable. You can build an empire on it.\n\nA religion based on knowledge is ungovernable. Once people realize they don't need the institution, they leave. They stop paying tithes. They stop following orders.\n\nThe church in the 4th century was becoming an empire. It had aligned with Rome. It had armies. It had wealth. It couldn't afford to let Gnosticism spread."),
        ],
        readingMinutes: 6,
        depthLabel: "Deep Abyss"
    )
    
    // MARK: - Layer 8: Eden Reread
    
    static let layer8_EdenReread = IcebergLayer(
        id: "gnostic_8",
        depth: 8,
        title: "Eden Was a Zoo",
        tagline: "The serpent told the truth. God lied. They woke up.",
        sections: [
            IcebergSection(heading: "The Gnostic Reading of Genesis", body: "God creates Adam and Eve. Puts them in a garden. One rule: don't eat from the tree of knowledge.\n\nWhy? God says: \"If you eat from it, you will surely die.\"\n\nThe serpent says: \"You will not die. Your eyes will be opened and you will be like gods, knowing good and evil.\"\n\nAdam and Eve eat the fruit. What happens?\n\nThey don't die. The serpent was right. Their eyes are opened. They become self-aware. They gain knowledge.\n\nAnd God's response? Fury. Exile. Punishment.\n\nThe orthodox interpretation: they sinned. They disobeyed.\n\nThe Gnostic question: Why would a benevolent creator forbid knowledge? Why would he threaten them with death for seeking understanding? Why would he punish curiosity?\n\nUnless the creator isn't benevolent. Unless Eden wasn't paradise — it was a zoo. A controlled environment where humans were kept in innocent ignorance. And the serpent — sent by Sophia, or perhaps Christ in disguise — offered liberation."),
            IcebergSection(heading: "The Tower of Babel", body: "After the flood, humanity starts working together. Building. Cooperating. They build a tower reaching the heavens.\n\nAnd God says: \"If as one people speaking the same language they have begun to do this, then nothing they plan to do will be impossible for them.\"\n\nRead that again. Nothing they plan to do will be impossible.\n\nThat's not a compliment. That's a threat assessment. God sees unified humanity as a danger.\n\nSo he confuses their language. Scatters them. Divides them. Ensures they can never cooperate on that scale again.\n\nThe Gnostics would say: unity, cooperation, the realization that humans working together could transcend the Demiurge's limitations. So he intervenes — not to protect them, but to stop them.\n\nThis pattern repeats throughout history. Every time humanity reaches a certain level of knowledge, something happens. War, plague, collapse. Almost like the system has a failsafe."),
        ],
        readingMinutes: 5,
        depthLabel: "Near Bottom"
    )
    
    // MARK: - Layer 9: The Implications
    
    static let layer9_Implications = IcebergLayer(
        id: "gnostic_9",
        depth: 9,
        title: "The Implications",
        tagline: "The question isn't why the world is broken. It's who built it that way.",
        sections: [
            IcebergSection(heading: "The Systematic Destruction", body: "In 313 AD, Emperor Constantine legalized Christianity — not from spiritual awakening, but political opportunity. In 325 AD, the Council of Nicaea established what Christianity would officially be. Everything else: heresy.\n\nGnostic texts were declared heretical. Teachers were executed. Communities were disbanded. Texts were hunted and burned. Libraries were raided. Anyone caught teaching Gnostic ideas was punished.\n\nThis wasn't theological disagreement. This was political purging. Gnosticism was incompatible with empire.\n\nFor 1,600 years, the only version of Christianity most people knew was the one approved by the Roman Empire."),
            IcebergSection(heading: "Ideas Don't Die", body: "Ideas go underground. They resurface.\n\nGnostic themes show up everywhere: in Kabbalah, in Sufism, in Hermeticism, in alchemy, in modern philosophy. The idea that the material world is a prison, that consciousness is divine, that knowledge is salvation.\n\nThese themes keep coming back in every culture, every generation — because they resonate with something deep in the human psyche.\n\nThe Gnostics believed the world was a simulation before simulation theory went mainstream. They believed in psychological programming before anyone used those words. They believed consciousness was non-local before quantum physics suggested the observer affects the observed."),
            IcebergSection(heading: "What If", body: "You don't have to believe it. You don't have to accept it as absolute truth. But you can hold it as a possibility — a lens, a way of seeing reality that explains things other frameworks don't.\n\nWhy does \"I want to go home\" resonate so deeply even when you're sitting in your own house?\n\nMaybe the feeling that something is fundamentally wrong with reality isn't a bug. It's a signal. A reminder that you don't belong here.\n\nOr maybe it's metaphor. The Demiurge is the ego. The Archons are limiting beliefs. The Pleroma is enlightened consciousness. Gnosis is self-awareness — the moment the illusion shatters.\n\nEither way, the practical application is real: question authority, seek direct experience over dogma, recognize how you imprison yourself, work to transcend conditioning, awaken what's already inside you."),
            IcebergSection(heading: "The Only Rebellion", body: "The only rebellion available is knowledge. The only weapon is awareness. The only escape is remembering what you are.\n\nYou are not your body. You are not your name. You are not your story.\n\nYou are the divine spark — the fragment of Sophia's light, the consciousness that observes all of this, that existed before birth and will exist after death.\n\nIf the world feels wrong, maybe the question isn't why it's broken.\n\nMaybe the question is who built it that way.\n\nAnd whether you're ready to see beyond what they built."),
        ],
        readingMinutes: 6,
        depthLabel: "The Bottom"
    )
}
